import { NextRequest, NextResponse } from 'next/server'
import { fetchAdzunaJobs } from '@/lib/apis/adzuna-api'
import { UnifiedJob } from '@/lib/types/job-types'

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams
  const query = searchParams.get('q') || ''
  const limit = parseInt(searchParams.get('limit') || '20')

  try {
    // Fetch only from Adzuna
    const jobs: UnifiedJob[] = await fetchAdzunaJobs({ query, limit })

    // Sort by posted date (newest first)
    jobs.sort((a, b) => b.posted.getTime() - a.posted.getTime())

    return NextResponse.json({
      success: true,
      data: jobs,
      count: jobs.length,
      source: 'adzuna'
    })
  } catch (error) {
    console.error('Jobs API error:', error)
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch jobs',
        message: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    )
  }
}
